package cn.zhuatech.esg.controller; import cn.zhuatech.esg.common.ApiResponse; import cn.zhuatech.esg.dto.EsgDto.*; import cn.zhuatech.esg.service.EsgService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('ESG_MANAGER','QUALITY','ADMIN')") public class SustainabilityAdminController {private final EsgService service;public SustainabilityAdminController(EsgService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<DisclosureTaskView>> orders(){return ApiResponse.ok(service.disclosureTasks());}}
